44	// 包含必有道路、避开禁用道路、全图连通。
45	func assertMapShape(t *testing.T, st State, req GenerateRequest) {
46		t.Helper()
47		edges := st.Rules.Edges
48		if len(edges) != req.RoadCount {
49			t.Fatalf("道路数量应为 %d，得到 %d: %v", req.RoadCount, len(edges), edges)
50		}
51		set := make(map[Edge]struct{}, len(edges))
52		for _, e := range edges {
53			if e.From >= e.To {
54				t.Fatalf("道路方向不规范: %+v", e)
55			}
56			if _, dup := set[e]; dup {
57				t.Fatalf("道路重复: %+v", e)
58			}
59			set[e] = struct{}{}
60		}
61		for _, r := range req.Required {
62			if _, ok := set[canonicalEdge(r)]; !ok {
63				t.Fatalf("必有道路 %+v 不在地图中: %v", r, edges)
64			}
65		}
