69			}
70		}
71		// 连通性：从任一地点出发应能到达全部地点。
72		adj := make(map[string][]string)
73		for _, e := range edges {
74			adj[e.From] = append(adj[e.From], e.To)
75			adj[e.To] = append(adj[e.To], e.From)
76		}
77		seen := map[string]struct{}{st.Rules.Locations[0]: {}}
78		queue := []string{st.Rules.Locations[0]}
79		for len(queue) > 0 {
80			cur := queue[0]
81			queue = queue[1:]
82			for _, nb := range adj[cur] {
83				if _, ok := seen[nb]; !ok {
84					seen[nb] = struct{}{}
85					queue = append(queue, nb)
86				}
87			}
88		}
