429		if err == nil {
430			t.Fatal("期望失败")
431		}
432		if w != nil {
433			t.Fatal("失败时不应产生可用世界")
434		}
435	}
436	
437	func TestGeneratedWorldApplyAndArchive(t *testing.T) {
438		req := baseGenerateRequest()
439		w := generateWorld(t, req)
440		st := w.Snapshot()
441	
442		// 沿生成的道路移动。
443		e := st.Rules.Edges[0]
444		hero := st.Characters[0]
445		from, to := e.From, e.To
446		if hero.Location == to {
447			from, to = to, from
448		}
449		// 先把 hero 放到道路一端（直接重建世界，避免多步移动）。
450		req.Characters = []Character{{ID: "hero", Location: from, Items: []CharacterItem{{Item: "gold", Count: 1}}}}
451		w = generateWorld(t, req)
452		if _, err := w.Apply(Commit{Moves: []Move{{Character: "hero", To: to}}, Time: 1}); err != nil {
453			t.Fatalf("沿生成道路移动失败: %v", err)
454		}
455	
456		// 存档后重新打开，地图来自记录而不是重新生成。
457		dir := t.TempDir()
458		a, err := Create(dir)
459		if err != nil {
460			t.Fatalf("Create: %v", err)
461		}
462		info, err := a.Save("slot", w)
