474		if !reflect.DeepEqual(st.Rules.Locations, rec.State.Rules.Locations) ||
475			!reflect.DeepEqual(w.Snapshot().Rules.Edges, rec.State.Rules.Edges) {
476			t.Fatal("重新打开后地图与记录不符")
477		}
478		// 读档重建的世界仍可按这些道路移动（沿同一条道路返回）。
479		w2, err := WorldFromState(rec.State)
480		if err != nil {
481			t.Fatalf("WorldFromState: %v", err)
482		}
483		if _, err := w2.Apply(Commit{Moves: []Move{{Character: "hero", To: from}}, Time: 2}); err != nil {
484			t.Fatalf("读档后沿道路移动失败: %v", err)
485		}
486	}
487	
